import React, { useState, useEffect } from 'react';
import {
  Container,
  Typography,
  Paper,
  TextField,
  Button,
  Box,
  Alert,
  Grid,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
} from '@mui/material';
import { useAuth } from '../context/AuthContext';

const Profile = () => {
  const { currentUser } = useAuth();
  const [formData, setFormData] = useState({});
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    if (currentUser) {
      // Initialize form data based on user role
      if (currentUser.role === 'student') {
        setFormData({
          personalInfo: currentUser.profile?.personalInfo || {},
          education: currentUser.profile?.education || {},
        });
      } else if (currentUser.role === 'institution') {
        setFormData({
          name: currentUser.profile?.name || '',
          phone: currentUser.profile?.phone || '',
          address: currentUser.profile?.address || '',
          description: currentUser.profile?.description || '',
        });
      } else if (currentUser.role === 'company') {
        setFormData({
          name: currentUser.profile?.name || '',
          industry: currentUser.profile?.industry || '',
          description: currentUser.profile?.description || '',
          contact: currentUser.profile?.contact || {},
          website: currentUser.profile?.website || '',
        });
      }
    }
  }, [currentUser]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    
    if (name.includes('.')) {
      const [parent, child] = name.split('.');
      setFormData(prev => ({
        ...prev,
        [parent]: {
          ...prev[parent],
          [child]: value
        }
      }));
    } else {
      setFormData(prev => ({
        ...prev,
        [name]: value
      }));
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    setError('');

    try {
      // This would call the appropriate API based on user role
      // For now, we'll just show a success message
      setMessage('Profile updated successfully!');
    } catch (err) {
      setError('Failed to update profile');
    } finally {
      setLoading(false);
    }
  };

  const renderStudentForm = () => (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <Typography variant="h6" gutterBottom>
          Personal Information
        </Typography>
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="First Name"
          name="personalInfo.firstName"
          value={formData.personalInfo?.firstName || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Last Name"
          name="personalInfo.lastName"
          value={formData.personalInfo?.lastName || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Phone"
          name="personalInfo.phone"
          value={formData.personalInfo?.phone || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Address"
          name="personalInfo.address"
          multiline
          rows={2}
          value={formData.personalInfo?.address || ''}
          onChange={handleChange}
        />
      </Grid>

      <Grid item xs={12}>
        <Typography variant="h6" gutterBottom>
          Education Information
        </Typography>
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="High School"
          name="education.highSchool"
          value={formData.education?.highSchool || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Graduation Year"
          name="education.graduationYear"
          type="number"
          value={formData.education?.graduationYear || ''}
          onChange={handleChange}
        />
      </Grid>
    </Grid>
  );

  const renderInstitutionForm = () => (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Institution Name"
          name="name"
          value={formData.name || ''}
          onChange={handleChange}
          required
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Phone"
          name="phone"
          value={formData.phone || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Address"
          name="address"
          multiline
          rows={2}
          value={formData.address || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Description"
          name="description"
          multiline
          rows={4}
          value={formData.description || ''}
          onChange={handleChange}
        />
      </Grid>
    </Grid>
  );

  const renderCompanyForm = () => (
    <Grid container spacing={3}>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Company Name"
          name="name"
          value={formData.name || ''}
          onChange={handleChange}
          required
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Industry"
          name="industry"
          value={formData.industry || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Website"
          name="website"
          value={formData.website || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12}>
        <TextField
          fullWidth
          label="Description"
          name="description"
          multiline
          rows={4}
          value={formData.description || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Contact Phone"
          name="contact.phone"
          value={formData.contact?.phone || ''}
          onChange={handleChange}
        />
      </Grid>
      <Grid item xs={12} sm={6}>
        <TextField
          fullWidth
          label="Contact Email"
          name="contact.email"
          value={formData.contact?.email || ''}
          onChange={handleChange}
        />
      </Grid>
    </Grid>
  );

  const renderForm = () => {
    switch (currentUser?.role) {
      case 'student':
        return renderStudentForm();
      case 'institution':
        return renderInstitutionForm();
      case 'company':
        return renderCompanyForm();
      case 'admin':
        return (
          <Typography>
            Admin profile management coming soon...
          </Typography>
        );
      default:
        return null;
    }
  };

  return (
    <Container maxWidth="md" sx={{ mt: 4, mb: 4 }}>
      <Paper elevation={3} sx={{ padding: 4 }}>
        <Typography variant="h4" gutterBottom>
          Profile
        </Typography>
        <Typography variant="body1" color="textSecondary" gutterBottom>
          Update your {currentUser?.role} profile information
        </Typography>

        {message && (
          <Alert severity="success" sx={{ mb: 2 }}>
            {message}
          </Alert>
        )}

        {error && (
          <Alert severity="error" sx={{ mb: 2 }}>
            {error}
          </Alert>
        )}

        <Box component="form" onSubmit={handleSubmit} sx={{ mt: 3 }}>
          {renderForm()}
          
          <Box sx={{ mt: 3 }}>
            <Button
              type="submit"
              variant="contained"
              disabled={loading}
              size="large"
            >
              {loading ? 'Updating...' : 'Update Profile'}
            </Button>
          </Box>
        </Box>
      </Paper>
    </Container>
  );
};

export default Profile;
